    const syncSamples=()=>{document.querySelectorAll('[data-variable-sample]').forEach(input=>samples[input.dataset.variableSample]=input.value);const names=variables(),target=$('#wa-variable-samples');target.innerHTML=names.length?names.map(name=>`<label><code>{{${safe(name)}}}</code><input data-variable-sample="${safe(name)}" value="${safe(samples[name]||'')}" placeholder="Example for ${safe(name)}" required></label>`).join(''):'<span class="empty compact">No variables detected.</span>';target.querySelectorAll('input').forEach(input=>input.addEventListener('input',()=>{samples[input.dataset.variableSample]=input.value;preview();}));};
    const applySamples=text=>{let output=String(text||'');for(const name of variables())output=output.replaceAll(`{{${name}}}`,samples[name]||`[${name}]`);return output;};
    const syncHeader=()=>{const type=form.elements.headerType.value,team=form.elements.teamId?.value||initial.ownerTeamId||'',types={image:['image/jpeg','image/png'],video:['video/mp4'],document:['application/pdf']};form.querySelector('[data-header-text]').hidden=type!=='text';form.querySelector('[data-header-media]').hidden=!types[type];[...form.elements.headerMaterialId.options].forEach(option=>{if(!option.value)return;option.hidden=Boolean((team&&option.dataset.team!==team)||!types[type]?.includes(option.dataset.media));});if(form.elements.headerMaterialId.selectedOptions[0]?.hidden)form.elements.headerMaterialId.value='';};
    const preview=()=>{const type=form.elements.headerType.value,material=data.materials.find(item=>String(item.id)===String(form.elements.headerMaterialId.value)),parts=values(),actionButtons=readButtons();let header='';if(type==='text'&&parts.header)header=`<b class="wa-preview-header">${safe(applySamples(parts.header))}</b>`;if(type==='image'&&material)header=`<img class="wa-preview-media" src="/api/crm/whatsapp-workspace/materials/${material.id}/file" alt="${safe(material.title)}">`;if(type==='video'&&material)header=`<video class="wa-preview-media" controls preload="metadata" src="/api/crm/whatsapp-workspace/materials/${material.id}/file"></video>`;if(type==='document'&&material)header=`<div class="wa-preview-document">PDF · ${safe(material.title)}</div>`;const buttonHtml=actionButtons.filter(item=>item.text).map(item=>{const url=item.type==='url'&&item.url?item.url.replace(/\{\{1\}\}$/,item.sampleValue||'[sample]'):'';return`<span class="wa-preview-button">${item.type==='url'?'↗':item.type==='phone_number'?'☎':'↩'} ${safe(item.text)}${url?`<small>${safe(url)}</small>`:item.phoneNumber?`<small>${safe(item.phoneNumber)}</small>`:''}</span>`;}).join('');$('#wa-template-preview').innerHTML=`<div class="wa-preview-bubble">${header}<div class="wa-preview-body">${safe(applySamples(parts.body)||'Your message body will appear here.').replaceAll('\n','<br>')}</div>${parts.footer?`<small class="wa-preview-footer">${safe(parts.footer)}</small>`:''}${buttonHtml?`<div class="wa-preview-buttons">${buttonHtml}</div>`:''}<time>12:34 ✓✓</time></div>`;for(const field of ['headerText','bodyText','footerText']){const counter=form.querySelector(`[data-count-for="${field}"]`);if(counter)counter.textContent=String(form.elements[field]?.value.length||0);}form.querySelectorAll('[data-button-count]').forEach(counter=>counter.textContent=String(counter.closest('[data-wa-button-row]').querySelector('[data-button-field="text"]').value.length));};
    const bindRows=()=>{buttons.querySelectorAll('[data-button-remove]').forEach(button=>button.onclick=()=>{button.closest('[data-wa-button-row]').remove();preview();});buttons.querySelectorAll('input').forEach(input=>input.addEventListener('input',preview));};
    const addButton=type=>{const current=readButtons();if(current.length>=10)return toast('Meta allows at most 10 buttons');if(type==='url'&&current.filter(item=>item.type==='url').length>=2)return toast('Meta allows at most 2 URL buttons');if(type==='phone_number'&&current.some(item=>item.type==='phone_number'))return toast('Meta allows at most 1 phone-number button');if(type==='quick_reply'){const firstNonQuick=buttons.querySelector('[data-button-type="url"],[data-button-type="phone_number"]');if(firstNonQuick)firstNonQuick.insertAdjacentHTML('beforebegin',buttonRow({type}));else buttons.insertAdjacentHTML('beforeend',buttonRow({type}));}else buttons.insertAdjacentHTML('beforeend',buttonRow({type}));bindRows();preview();};
    $('#wa-add-url').insertAdjacentHTML('afterend','<button type="button" class="btn btn-sm" id="wa-add-phone">Add phone</button>');$('#wa-add-quick').onclick=()=>addButton('quick_reply');$('#wa-add-url').onclick=()=>addButton('url');$('#wa-add-phone').onclick=()=>addButton('phone_number');
    form.elements.headerType.addEventListener('change',()=>{syncHeader();syncSamples();preview();});form.elements.teamId?.addEventListener('change',()=>{syncHeader();preview();});form.elements.headerMaterialId.addEventListener('change',preview);
