    document.querySelectorAll('[data-template-version]').forEach(button=>button.onclick=()=>{const item=data.templates.find(x=>x.id===button.dataset.templateVersion);templateMode={kind:'version',template:{...item,versionId:'',bodyText:item.bodyText,headerText:item.headerText,footerText:item.footerText}};render();});
    document.querySelectorAll('[data-template-submit]').forEach(button=>button.onclick=async()=>{if(!confirm('Submit this exact template version for internal Manager/Director review?'))return;try{await api(`/crm/whatsapp-workspace/template-versions/${button.dataset.templateSubmit}/submit`,{method:'POST',body:{}});await refresh('Template submitted for internal review');}catch(error){toast(error.message,9000);}});
    document.querySelectorAll('[data-template-decision]').forEach(button=>button.onclick=async()=>{const returning=button.dataset.decision==='return',reason=returning?prompt('Reason for returning this template:','')||'':'';if(returning&&reason.trim().length<5)return toast('Enter a clear return reason');if(!returning&&!confirm('Approve this exact template version internally? Meta status will remain Not submitted.'))return;try{await api(`/crm/whatsapp-workspace/template-versions/${button.dataset.templateDecision}/decision`,{method:'POST',body:{decision:button.dataset.decision,reason}});await refresh(`Template ${returning?'returned':'approved internally'}`);}catch(error){toast(error.message,9000);}});
    bindRecipientCommit();
    if(recipientForm){recipientForm.insertAdjacentHTML('beforebegin','<p><a class="btn btn-sm" href="/templates/whatsapp-recipient-import-template.xlsx" download>Download approved Excel template</a></p>');const note=recipientForm.querySelector('.tool-note');if(note)note.textContent='Required: name, phone. Optional: email, tags, source_detail, consent_status, consent_evidence_ref, transaction_type, area, budget_max, project, property_type, bedrooms, timeframe, language, owner_id. Unknown layouts open a column-mapping step. Purchased-list provenance is mandatory when that source is selected.';}
    if(recipientForm)recipientForm.onsubmit=async event=>{event.preventDefault();const file=recipientForm.elements.file.files[0];if(!file)return;try{const body=Object.fromEntries(new FormData(recipientForm));delete body.file;body.originalFileName=file.name;body.mediaType=file.type;body.base64=await fileBase64(file);recipientRows=body;recipientPreview=await api('/crm/whatsapp-workspace/recipient-imports/preview',{method:'POST',body});recipientPreview.teamId=body.teamId;$('#wa-recipient-preview').innerHTML=recipientPreviewHtml();bindRecipientCommit();}catch(error){toast(error.message,9000);}};
    const consentSelect=$('#wa-segment-form select[name="consentStatus"]');if(consentSelect)consentSelect.innerHTML='<option value="">Any recorded state</option><option value="verified">Verified</option><option value="evidence_pending">Evidence pending</option><option value="withdrawn">Withdrawn</option><option value="denied">Denied</option>';
    const segmentForm=$('#wa-segment-form');if(segmentForm)segmentForm.onsubmit=async event=>{event.preventDefault();const body=Object.fromEntries(new FormData(segmentForm)),list=value=>String(value||'').split(',').map(x=>x.trim()).filter(Boolean);body.definition={tagsAny:list(body.tagsAny),sources:list(body.sources),areasAny:list(body.areasAny),transactionTypes:list(body.transactionTypes),projects:list(body.projects),propertyTypes:list(body.propertyTypes),bedroomsMin:body.bedroomsMin||null,bedroomsMax:body.bedroomsMax||null,timeframes:list(body.timeframes),languages:list(body.languages),ownerIds:list(body.ownerIds),consentStatus:body.consentStatus||null,budgetMin:body.budgetMin||null,budgetMax:body.budgetMax||null};try{await api('/crm/whatsapp-workspace/segments',{method:'POST',body});await refresh('Segment saved');}catch(error){toast(error.message,9000);}};
    document.querySelectorAll('[data-segment-retire]').forEach(button=>button.onclick=async()=>{if(!confirm('Retire this segment? Existing campaign history remains.'))return;try{await api(`/crm/whatsapp-workspace/segments/${button.dataset.segmentRetire}/retire`,{method:'POST',body:{}});await refresh('Segment retired');}catch(error){toast(error.message,9000);}});
